/// Tests only: the JSON of `of_json_key` of the key of a fact of the
/// predicate `name` (`"ClassDeclaration"`), `None` for a name that is
/// not a predicate of this module.
#[cfg(test)]
pub fn round_trip_key(name: &str, key: &crate::yojson::safe::T) -> Option<crate::yojson::safe::T> {
    match name {
        "IndexFailure" => Some(index_failure::to_json_key(&index_failure::of_json_key(key))),
        "FileLines" => Some(file_lines::to_json_key(&file_lines::of_json_key(key))),
        "FileLanguage" => Some(file_language::to_json_key(&file_language::of_json_key(key))),
        "FileContent" => Some(file_content::to_json_key(&file_content::of_json_key(key))),
        "ByteSpanContains" => Some(byte_span_contains::to_json_key(&byte_span_contains::of_json_key(key))),
        "File" => Some(file::to_json_key(&file::of_json_key(key))),
        "RangeContains" => Some(range_contains::to_json_key(&range_contains::of_json_key(key))),
        "FileDigest" => Some(file_digest::to_json_key(&file_digest::of_json_key(key))),
        _ => None,
    }
}
